package com.example.techfix.ui;
import android.view.*; import android.widget.TextView; import androidx.recyclerview.widget.RecyclerView; import com.example.techfix.R; import com.example.techfix.data.entity.RepairService; import java.util.List;
public class ServiceAdapter extends RecyclerView.Adapter<ServiceAdapter.ViewHolder>{ public interface Listener{void onClick(RepairService s);} private final List<RepairService> list; private final Listener listener; public ServiceAdapter(List<RepairService> l,Listener x){list=l;listener=x;} public static class ViewHolder extends RecyclerView.ViewHolder{TextView name,description,price;ViewHolder(View v){super(v);name=v.findViewById(R.id.tvServiceName);description=v.findViewById(R.id.tvServiceDescription);price=v.findViewById(R.id.tvServicePrice);}} @Override public ViewHolder onCreateViewHolder(ViewGroup p,int t){return new ViewHolder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_service,p,false));} @Override public void onBindViewHolder(ViewHolder h,int pos){RepairService s=list.get(pos);h.name.setText(s.getName());h.description.setText(s.getDescription());h.price.setText(String.format("Rs. %.2f",s.getPrice()));h.itemView.setOnClickListener(v->listener.onClick(s));} @Override public int getItemCount(){return list.size();}}
